def shortest_path(graph, source, target):
    from heapq import heappop, heappush

    def dijkstra(graph, source, target):
        result = {}
        q = [(0, source)]
        while q:
            dist, v = heappop(q)
            if v in result:
                continue
            result[v] = dist
            if v == target:
                return result
            for w, weight in graph.get(v, []):
                if w in result:
                    continue
                heappush(q, (dist + weight, w))
        return result
    distances = dijkstra(graph, source, target)
    if target not in distances:
        return (float('inf'), None)
    else:
        return (distances[target], [target] + [pre for dist, pre in dijkstra(graph, target, source)[target:][::-1]])
